uint8_t FolderComparator::SpecialFlagsOrder(const uint32_t flags) const {
  if (flags & nsMsgFolderFlags::Inbox) return 0;
  if (flags & nsMsgFolderFlags::Drafts) return 1;
  if (flags & nsMsgFolderFlags::Templates) return 2;
  if (flags & nsMsgFolderFlags::SentMail) return 3;
  if (flags & nsMsgFolderFlags::Archive) return 4;
  if (flags & nsMsgFolderFlags::Junk) return 5;
  if (flags & nsMsgFolderFlags::Trash) return 6;
  if (flags & nsMsgFolderFlags::Virtual) return 7;
  if (flags & nsMsgFolderFlags::Queue) return 8;
  return 9;

/**
 * Tests folders that all have an ordinal value.
 */
add_task(function testNullOrdinals() {
  const parent = 7;
  const echo = 10; // Lowercase E with diaeresis.
  const foxtrot = 9; // Uppercase F.
  const golf = 15;
  const hotel = 3; // Uppercase H.

  Assert.deepEqual(folderDB.getFolderChildren(parent), [
    echo,
    foxtrot,
    golf,
    hotel,
  ]);

/**
 * Tests folders that all have no ordinal value.
 */
add_task(function testNonNullOrdinals() {
  const parent = 12;
  const kilo = 6;
  const lima = 2; // Uppercase L.
  const november = 14; // Uppercase N.
  const quebec = 8; // Uppercase Q.

  Assert.deepEqual(folderDB.getFolderChildren(parent), [
    lima,
    quebec,
    kilo,
    november,
  ]);
